// Atalhos de criação a partir dos campos da viagem; nunca inventar NIF ou morada de faturação.
function createCompanyFromTrip(type){const f=$("tripForm").elements,name=String(f["empresa_"+type].value||"").trim();if(!name){msg("Primeiro confirma o nome da empresa de "+type+" na viagem.");return}const existing=findCompanyByName(name);if(existing){page("companies");$("companySearch").value=name;renderCompanies();msg("Esta empresa já existe no índice. Podes editar a ficha existente.");return}resetCompany();const c=$("companyForm").elements;c.nome.value=name;c.designacao_social.value=name;c.morada_operacional.value=String(f["morada_"+type].value||"").trim();c.localidade.value=String(f["local_"+type].value||"").trim();c.fonte_dados.value="documento";c.verificado.checked=false;updateCompanyZoneSuggestion();page("companies");$("companyTitle").textContent="Nova empresa de "+type+" — confirmar dados";$("companyForm").scrollIntoView({behavior:"smooth"});msg("Ficha pré-preenchida. Confirma a designação social, NIF e morada de faturação antes de guardar.")}
$("createCompanyCarga").onclick=()=>createCompanyFromTrip("carga");$("createCompanyDescarga").onclick=()=>createCompanyFromTrip("descarga");
// Índice privado de empresas: faturação distinta dos locais operacionais.
// Agrupamento operacional Norte/Centro/Sul, não uma divisão administrativa oficial.
// Não atribuir zona com base em prefixos ambíguos; a escolha manual prevalece.
const companyZones={norte:["braga","braganca","porto","viana do castelo","vila real"],centro:["aveiro","castelo branco","coimbra","guarda","leiria","santarem","viseu"],sul:["beja","evora","faro","portalegre","setubal"]};
const companyTowns={norte:["porto","braga","braganca","guimaraes","famalicao","trofa","maia","matosinhos","gondomar","valongo","povoa de varzim","vila do conde","barcelos","viana do castelo","vila real","chaves","mirandela","mogadouro","amarante","felgueiras","penafiel","santo tirso","sao mamede do coronado"],centro:["aveiro","coimbra","leiria","viseu","guarda","castelo branco","santarem","figueira da foz","marinha grande","pombal","alcobaca","caldas da rainha","torres novas","abrantes","covilha","fundao"],sul:["faro","beja","evora","portalegre","setubal","almada","seixal","barreiro","montijo","palmela","sesimbra","sines","grandola","albufeira","loule","lagos","portimao","tavira","silves","odemira"]};
function normalizedZoneText(s){return String(s||"").normalize("NFD").replace(/[\u0300-\u036f]/g,"").toLowerCase().replace(/[^a-z0-9]+/g," ").trim()}
function suggestCompanyZone(f){const district=normalizedZoneText(f.distrito.value),locality=normalizedZoneText(f.localidade.value),address=normalizedZoneText(f.morada_operacional.value||f.morada_faturacao.value);for(const [zone,names]of Object.entries(companyZones)){if(names.includes(district))return {zone,reason:"distrito"}}const matches=[];for(const [zone,names]of Object.entries(companyTowns)){if(names.some(name=>locality===name||locality.endsWith(" "+name)||address.includes(" "+name+" ")||address.endsWith(" "+name)))matches.push(zone)}if(new Set(matches).size===1)return {zone:matches[0],reason:"localidade"};const prefix=String(f.codigo_postal.value||"").match(/^(\d{4})-?\d{0,3}$/)?.[1];if(prefix){const first=Number(prefix[0]);if(first===3||first===6)return {zone:"centro",reason:"código postal (aproximado)"};if(first===4||first===5)return {zone:"norte",reason:"código postal (aproximado)"};if(first===7||first===8)return {zone:"sul",reason:"código postal (aproximado)"}}return null}
let companyZoneManual=false;function updateCompanyZoneSuggestion(){const f=companyForm.elements,guess=suggestCompanyZone(f),hint=$("companyZoneHint");if(!companyZoneManual){f.zona.value=guess?.zone||"por_classificar"}hint.textContent=companyZoneManual?"Zona escolhida manualmente.":guess?"Sugestão automática por "+guess.reason+": "+({norte:"Norte",centro:"Centro",sul:"Sul"}[guess.zone])+". Podes corrigir.":"Zona por classificar: indica distrito, localidade ou código postal."}

let companyMap=null,companyMarkers=null,leafletPromise=null;
function loadLeaflet(){if(window.L)return Promise.resolve(window.L);if(!leafletPromise)leafletPromise=new Promise((resolve,reject)=>{const s=document.createElement("script");s.src="https://unpkg.com/leaflet@1.9.4/dist/leaflet.js";s.onload=()=>window.L?resolve(window.L):reject(new Error("Mapa indisponível"));s.onerror=()=>reject(new Error("Não foi possível carregar o mapa"));document.head.appendChild(s)});return leafletPromise}
async function renderCompanyMap(){const root=$("companyMap");if(!root||$("companies").classList.contains("hidden"))return;const status=$("companyMapStatus");try{const L=await loadLeaflet();if($("companies").classList.contains("hidden"))return;if(!companyMap){companyMap=L.map(root,{scrollWheelZoom:false}).setView([39.55,-8],7);L.tileLayer("https://{s}.tile.openstreetmap.org/{z}/{x}/{y}.png",{maxZoom:19,attribution:"© OpenStreetMap contributors"}).addTo(companyMap);companyMarkers=L.layerGroup().addTo(companyMap)}companyMap.invalidateSize();companyMarkers.clearLayers();const q=$("companySearch").value.trim().toLocaleLowerCase("pt-PT"),zone=$("companyZoneFilter").value;const filtered=companies.filter(c=>(!zone||c.zona===zone)&&[c.nome,c.designacao_social,c.nif,c.localidade,c.codigo_postal,c.distrito].some(v=>String(v||"").toLocaleLowerCase("pt-PT").includes(q)));let plotted=0;for(const c of filtered){if(c.latitude==null||c.longitude==null)continue;const lat=Number(c.latitude),lon=Number(c.longitude);if(!Number.isFinite(lat)||!Number.isFinite(lon)||lat< -90||lat>90||lon< -180||lon>180)continue;const url="https://www.google.com/maps/dir/?api=1&destination="+encodeURIComponent(lat+","+lon);const popup="<b>"+esc(c.nome)+"</b><p>"+esc([c.morada_operacional,c.localidade].filter(Boolean).join(", "))+"</p><a href=\""+esc(url)+"\" target=\"_blank\" rel=\"noopener noreferrer\">🧭 Navegar para este ponto</a>";L.marker([lat,lon]).bindPopup(popup).addTo(companyMarkers);plotted++}status.textContent=plotted+" empresa(s) com GPS no mapa · "+(filtered.length-plotted)+" sem coordenadas. Confirma acessos para pesados."}catch(e){status.textContent="Não foi possível carregar o mapa. A lista de empresas continua disponível.";console.error(e)}}
$("companyMapReset").onclick=()=>{if(companyMap){companyMap.setView([39.55,-8],7);companyMap.invalidateSize()}};
$("companyCaptureGPS").onclick=()=>{if(!navigator.geolocation){msg("GPS indisponível.");return}const btn=$("companyCaptureGPS"),status=$("companyGPSStatus");btn.disabled=true;status.textContent="A obter coordenadas…";navigator.geolocation.getCurrentPosition(p=>{companyForm.elements.latitude.value=p.coords.latitude.toFixed(7);companyForm.elements.longitude.value=p.coords.longitude.toFixed(7);status.textContent="Precisão aproximada: "+Math.round(p.coords.accuracy)+" m. Confirma a posição.";btn.disabled=false},e=>{status.textContent=e.code===1?"Autoriza a localização no telemóvel.":"Não foi possível obter GPS.";btn.disabled=false},{enableHighAccuracy:true,timeout:20000,maximumAge:0})};
const companyForm=$("companyForm");function resetCompany(){companyForm.reset();companyZoneManual=false;updateCompanyZoneSuggestion();editCompany=null;$("companyTitle").textContent="Nova ficha de empresa"}function renderCompanies(){const q=$("companySearch").value.trim().toLocaleLowerCase("pt-PT"),zone=$("companyZoneFilter").value;const items=companies.filter(c=>(!zone||c.zona===zone)&&[c.nome,c.designacao_social,c.nif,c.localidade,c.codigo_postal,c.distrito].some(v=>String(v||"").toLocaleLowerCase("pt-PT").includes(q)));const groups=[["norte","Norte"],["centro","Centro"],["sul","Sul"],["por_classificar","Por classificar"]];$("companyResults").innerHTML=groups.map(([key,label])=>{const list=items.filter(c=>c.zona===key);if(!list.length)return "";return '<h3>'+label+' ('+list.length+')</h3>'+list.map(c=>'<div class="item"><div><b>'+esc(c.designacao_social||c.nome)+'</b><div class="muted">NIF: '+esc(c.nif||"Por confirmar")+' · '+esc([c.codigo_postal,c.localidade].filter(Boolean).join(" "))+'</div><div class="muted">Faturação: '+esc(c.morada_faturacao||"Por preencher")+' · '+(c.verificado?"Dados confirmados":"Não verificado")+'</div><div class="muted">Carga/descarga: '+esc(c.morada_operacional||"Por preencher")+'</div></div><div><button type="button" data-company-edit="'+c.id+'">Editar</button> <button type="button" data-company-use="'+c.id+'">Usar na viagem</button> <button type="button" data-company-delete="'+c.id+'">Eliminar</button></div></div>').join("")}).join("")||'<p class="muted">Não foram encontradas empresas. Podes criar uma ficha abaixo.</p>';renderCompanyMap()} for(const field of ["distrito","localidade","codigo_postal","morada_operacional","morada_faturacao"]){companyForm.elements[field].addEventListener("input",updateCompanyZoneSuggestion)}companyForm.elements.zona.addEventListener("change",()=>{companyZoneManual=true;updateCompanyZoneSuggestion()});$("companySearch").oninput=renderCompanies;$("companyZoneFilter").onchange=renderCompanies;$("clearCompany").onclick=resetCompany;$("lookupCompany").onclick=()=>{const name=companyForm.elements.designacao_social.value||companyForm.elements.nome.value||$("companySearch").value;if(!name.trim()){msg("Indica primeiro o nome da empresa.");return}window.open("https://www.google.com/search?q="+encodeURIComponent('"'+name+'" NIF morada sede Portugal'),"_blank","noopener,noreferrer")};companyForm.onsubmit=async e=>{e.preventDefault();const f=new FormData(companyForm),data={user_id:user.id};for(const [k,v]of f){if(k!=="verificado")data[k]=String(v).trim()||null}data.verificado=f.has("verificado");for(const k of ["latitude","longitude"])data[k]=data[k]==null?null:Number(data[k]);if((data.latitude===null)!==(data.longitude===null)){msg("Preenche as duas coordenadas ou deixa ambas vazias.");return}data.zona=data.zona||"por_classificar";if(data.nif&&!/^\d{9}$/.test(data.nif)){msg("O NIF deve ter exatamente 9 algarismos.");return}const {error}=editCompany?await db.from("empresas").update(data).eq("id",editCompany):await db.from("empresas").insert(data);if(error){msg(error.message);return}resetCompany();await load();page("companies");msg("Ficha da empresa guardada.")};document.addEventListener("click",async e=>{const btn=e.target.closest("[data-company-edit],[data-company-delete],[data-company-use]");if(!btn)return;const id=btn.dataset.companyEdit||btn.dataset.companyDelete||btn.dataset.companyUse,c=companies.find(x=>x.id===id);if(!c)return;if(btn.dataset.companyEdit){resetCompany();editCompany=c.id;$("companyTitle").textContent="Editar empresa: "+c.nome;for(const [k,v]of Object.entries(c)){const input=companyForm.elements.namedItem(k);if(input&&k!=="verificado")input.value=v??""}companyForm.elements.verificado.checked=!!c.verificado;companyZoneManual=true;updateCompanyZoneSuggestion();page("companies");companyForm.scrollIntoView({behavior:"smooth"})}else if(btn.dataset.companyDelete){if(!confirm("Eliminar esta empresa do índice?"))return;const {error}=await db.from("empresas").delete().eq("id",id);if(error)msg(error.message);else{await load();msg("Empresa eliminada.")}}else{const f=$("tripForm").elements;const type=confirm("Utilizar como empresa de CARGA?\nOK = carga · Cancelar = descarga")?"carga":"descarga";f["empresa_"+type].value=c.designacao_social||c.nome;f["morada_"+type].value=c.morada_operacional||c.morada_faturacao||"";f["local_"+type].value=c.localidade||"";page("trip");msg("Empresa colocada na viagem. Confirma a morada operacional.")}});

// Estimativa rodoviária: serviço público de demonstração OSRM, sem perfil de pesados.
let plannerMap=null,plannerMapLayers=null,plannerRequest=0;
function plannerCoords(stop){const a=Number(stop.latitude),b=Number(stop.longitude);return stop.latitude!=null&&stop.longitude!=null&&Number.isFinite(a)&&Number.isFinite(b)&&a>=-90&&a<=90&&b>=-180&&b<=180?[a,b]:null}
async function showPlannerMap(calculate=false){const id=++plannerRequest,status=$("plannerDistance"),legs=$("plannerLegs");if($("planner").classList.contains("hidden"))return;try{const L=await loadLeaflet();if(id!==plannerRequest)return;if(!plannerMap){plannerMap=L.map("plannerMap",{scrollWheelZoom:false}).setView([39.55,-8],7);L.tileLayer("https://{s}.tile.openstreetmap.org/{z}/{x}/{y}.png",{maxZoom:19,attribution:"© OpenStreetMap contributors"}).addTo(plannerMap);plannerMapLayers=L.layerGroup().addTo(plannerMap)}plannerMap.invalidateSize();plannerMapLayers.clearLayers();legs.textContent="";const known=plannerStops.map((s,i)=>({s,i,coords:plannerCoords(s)})).filter(x=>x.coords);const bounds=[];for(const x of known){L.marker(x.coords).bindPopup("<b>"+esc((x.i+1)+". "+(x.s.nome||"Paragem"))+"</b><p>"+esc(x.s.morada||"GPS guardado")+"</p>").addTo(plannerMapLayers);bounds.push(x.coords)}if(bounds.length)plannerMap.fitBounds(bounds,{padding:[25,25],maxZoom:13});else plannerMap.setView([39.55,-8],7);if(!calculate){status.textContent=known.length+" de "+plannerStops.length+" paragens com GPS. Carrega em calcular para obter as distâncias.";return}if(plannerStops.length<2){status.textContent="Adiciona pelo menos duas paragens.";return}if(known.length!==plannerStops.length){status.textContent="Para calcular distâncias rodoviárias, todas as paragens precisam de coordenadas GPS. Guarda o GPS nas fichas de empresas e volta a adicioná-las ao plano.";return}if(known.length>10){status.textContent="Calcula no máximo 10 paragens de cada vez.";return}status.textContent="A consultar o serviço de rotas…";const coordinates=known.map(x=>x.coords[1]+","+x.coords[0]).join(";");const url="https://router.project-osrm.org/route/v1/driving/"+coordinates+"?overview=full&geometries=geojson&steps=false";const controller=new AbortController();const timeout=setTimeout(()=>controller.abort(),15000);let response;try{response=await fetch(url,{signal:controller.signal})}finally{clearTimeout(timeout)}if(!response.ok)throw Error("Serviço de rotas indisponível");const data=await response.json();if(id!==plannerRequest)return;const route=data.routes?.[0];if(data.code!=="Ok"||!route||!Array.isArray(route.legs)||route.legs.length!==plannerStops.length-1)throw Error("Sem rota rodoviária disponível");const line=route.geometry?.coordinates?.map(c=>[c[1],c[0]]);if(line?.length){const poly=L.polyline(line,{color:"#2165dd",weight:5,opacity:.8}).addTo(plannerMapLayers);plannerMap.fitBounds(poly.getBounds(),{padding:[25,25]})}const km=(n)=>(n/1000).toLocaleString("pt-PT",{maximumFractionDigits:1});status.textContent="Distância rodoviária indicativa: "+km(route.distance)+" km. Rota para automóveis, NÃO validada para pesados. Não inclui trânsito em tempo real.";legs.innerHTML=route.legs.map((leg,i)=>'<div class="item"><div><b>'+esc(plannerStops[i].nome||"Paragem "+(i+1))+' → '+esc(plannerStops[i+1].nome||"Paragem "+(i+2))+'</b><div class="muted">'+km(leg.distance)+' km · percurso indicativo para automóveis</div></div></div>').join("")}catch(e){if(id!==plannerRequest)return;status.textContent="Não foi possível calcular a distância rodoviária agora. Podes continuar a usar a rota no Google Maps. "+e.message}}
$("plannerCalculate").onclick=()=>showPlannerMap(true);
/* Planeador: paragens ordenadas, persistência privada e navegação externa. */
const plannerForm=$("plannerForm");
function plannerStopRow(s,i){return '<div class="card" style="margin:10px 0"><b>Paragem '+(i+1)+'</b><div class="fields"><div><label>Tipo</label><select data-stop-field="tipo" data-stop-index="'+i+'"><option value="carga" '+(s.tipo==="carga"?"selected":"")+'>Carga</option><option value="descarga" '+(s.tipo==="descarga"?"selected":"")+'>Descarga</option><option value="pausa" '+(s.tipo==="pausa"?"selected":"")+'>Pausa</option><option value="outro" '+(s.tipo==="outro"?"selected":"")+'>Outro</option></select></div><div><label>Empresa / local</label><input data-stop-field="nome" data-stop-index="'+i+'" value="'+esc(s.nome||"")+'"></div><div><label>Morada para navegação</label><input data-stop-field="morada" data-stop-index="'+i+'" value="'+esc(s.morada||"")+'"></div><div><label>Hora prevista (opcional)</label><input type="time" data-stop-field="hora" data-stop-index="'+i+'" value="'+esc(s.hora||"")+'"></div></div><p><button type="button" data-stop-up="'+i+'" '+(i===0?"disabled":"")+'>↑ Subir</button> <button type="button" data-stop-down="'+i+'" '+(i===plannerStops.length-1?"disabled":"")+'>↓ Descer</button> <button type="button" data-stop-remove="'+i+'">Remover</button></p></div>'}
function renderPlanner(){if(plannerMap){plannerRequest++;plannerMapLayers.clearLayers();$("plannerDistance").textContent="Percurso alterado. Volta a calcular as distâncias.";$("plannerLegs").textContent=""}const select=$("plannerCompany"),old=select.value;select.innerHTML='<option value="">Escolher empresa guardada…</option>'+companies.map(c=>'<option value="'+esc(c.id)+'">'+esc(c.nome)+' · '+esc(c.localidade||"")+'</option>').join("");if(companies.some(c=>c.id===old))select.value=old;$("plannerStops").innerHTML=plannerStops.map(plannerStopRow).join("")||'<p class="muted">Adiciona pelo menos duas paragens para criar uma rota.</p>';$("plannerList").innerHTML=plans.map(p=>'<div class="item"><div><b>'+esc(p.titulo)+'</b><div class="muted">'+esc(p.data_viagem||"Sem data")+' · '+(Array.isArray(p.paragens)?p.paragens.length:0)+' paragens · '+esc(p.matricula||"Sem matrícula")+'</div></div><div><button type="button" data-plan-edit="'+p.id+'">Abrir</button> <button type="button" data-plan-delete="'+p.id+'">Eliminar</button></div></div>').join("")||'<p class="muted">Ainda não existem planos guardados.</p>'}
function clearPlanner(){plannerForm.reset();editPlan=null;plannerStops=[];$("plannerStatus").textContent="";renderPlanner()}
$("plannerClear").onclick=clearPlanner;
$("plannerTruckGPS").onclick=()=>{const button=$("plannerTruckGPS"),status=$("plannerTruckGPSStatus");if(!navigator.geolocation){status.textContent="O navegador não disponibiliza GPS.";return}button.disabled=true;status.textContent="A obter a localização do telemóvel…";navigator.geolocation.getCurrentPosition(p=>{const lat=p.coords.latitude,lon=p.coords.longitude,accuracy=Math.round(p.coords.accuracy);if(!Number.isFinite(lat)||!Number.isFinite(lon)){status.textContent="Coordenadas inválidas.";button.disabled=false;return}plannerStops.unshift({tipo:"outro",nome:"Localização atual do camião (telemóvel)",morada:"",hora:"",latitude:lat,longitude:lon,gps_origem:true});renderPlanner();status.textContent="Ponto inicial adicionado pelo GPS do telemóvel (precisão aproximada: "+accuracy+" m). Confirma que o telemóvel está no camião. A posição é pontual, não é acompanhamento em tempo real.";button.disabled=false;showPlannerMap(false)},e=>{status.textContent=e.code===1?"Permissão de localização recusada. Autoriza o GPS para este site.":e.code===3?"Tempo esgotado ao procurar GPS. Tenta novamente.":"Não foi possível obter a localização. Verifica o GPS e a ligação.";button.disabled=false},{enableHighAccuracy:true,timeout:20000,maximumAge:0})};
$("plannerRefreshGPS").onclick=()=>{const button=$("plannerRefreshGPS"),status=$("plannerTruckGPSStatus");if(!navigator.geolocation){status.textContent="O navegador não disponibiliza GPS.";return}const first=plannerStops[0];if(!first||!first.gps_origem&&first.nome!=="Localização atual do camião (telemóvel)"){status.textContent="Primeiro adiciona a localização do camião como ponto de partida.";return}button.disabled=true;status.textContent="A atualizar a posição GPS…";navigator.geolocation.getCurrentPosition(p=>{const lat=p.coords.latitude,lon=p.coords.longitude,accuracy=Math.round(p.coords.accuracy);if(!Number.isFinite(lat)||!Number.isFinite(lon)){status.textContent="Coordenadas inválidas.";button.disabled=false;return}first.latitude=lat;first.longitude=lon;first.gps_origem=true;renderPlanner();status.textContent="Posição inicial atualizada (precisão aproximada: "+accuracy+" m). As restantes paragens foram mantidas. A recalcular percurso…";button.disabled=false;showPlannerMap(true)},e=>{status.textContent=e.code===1?"Permissão de localização recusada.":"Não foi possível atualizar o GPS. Tenta novamente.";button.disabled=false},{enableHighAccuracy:true,timeout:20000,maximumAge:0})};
$("plannerAddStop").onclick=()=>{plannerStops.push({tipo:"carga",nome:"",morada:"",hora:""});renderPlanner()};
$("plannerAddCompany").onclick=()=>{const c=companies.find(c=>c.id===$("plannerCompany").value);if(!c){msg("Seleciona uma empresa do índice.");return}plannerStops.push({tipo:"carga",nome:c.nome,morada:c.morada_operacional||c.morada_faturacao||"",hora:"",empresa_id:c.id,latitude:c.latitude,longitude:c.longitude});renderPlanner()};
$("plannerStops").addEventListener("input",e=>{const el=e.target.closest("[data-stop-field]");if(el){const stop=plannerStops[Number(el.dataset.stopIndex)];stop[el.dataset.stopField]=el.value;if(el.dataset.stopField==="morada"){stop.latitude=null;stop.longitude=null}}});
$("plannerStops").addEventListener("change",e=>{const el=e.target.closest("[data-stop-field]");if(el){const stop=plannerStops[Number(el.dataset.stopIndex)];stop[el.dataset.stopField]=el.value;if(el.dataset.stopField==="morada"){stop.latitude=null;stop.longitude=null}}});
$("plannerStops").addEventListener("click",e=>{const b=e.target.closest("[data-stop-up],[data-stop-down],[data-stop-remove]");if(!b)return;const i=Number(b.dataset.stopUp??b.dataset.stopDown??b.dataset.stopRemove);if(b.hasAttribute("data-stop-remove"))plannerStops.splice(i,1);else{const k=b.hasAttribute("data-stop-up")?i-1:i+1;if(k<0||k>=plannerStops.length)return;[plannerStops[i],plannerStops[k]]=[plannerStops[k],plannerStops[i]]}renderPlanner()});
function plannerDestination(s){return s.latitude!=null&&s.longitude!=null&&Number.isFinite(Number(s.latitude))&&Number.isFinite(Number(s.longitude))?s.latitude+","+s.longitude:String(s.morada||"").trim()}
$("plannerNavigate").onclick=()=>{if(plannerStops.length<2){msg("Adiciona pelo menos duas paragens.");return}if(plannerStops.some(s=>!plannerDestination(s))){msg("Todas as paragens precisam de morada ou coordenadas GPS.");return}if(plannerStops.length>10){msg("Para evitar limites do Google Maps, divide a rota em grupos de até 10 paragens.");return}const destinations=plannerStops.map(plannerDestination);const params=new URLSearchParams({api:"1",origin:destinations[0],destination:destinations.at(-1),travelmode:"driving"});if(destinations.length>2)params.set("waypoints",destinations.slice(1,-1).join("|"));window.open("https://www.google.com/maps/dir/?"+params.toString(),"_blank","noopener,noreferrer");$("plannerStatus").textContent="Rota enviada para o Google Maps. Atenção: não valida peso, altura, eixos, comprimento nem acessos para pesados."};
plannerForm.onsubmit=async e=>{e.preventDefault();if(plannerStops.length<2){msg("Regista pelo menos duas paragens.");return}const data={user_id:user.id,paragens:plannerStops.map(s=>({...s}))};for(const [k,v]of new FormData(plannerForm))data[k]=String(v).trim()||null;for(const k of ["peso_bruto_t","eixos","altura_m","largura_m","comprimento_m"])data[k]=data[k]==null?null:Number(data[k]);const {error}=editPlan?await db.from("planos_viagem").update(data).eq("id",editPlan):await db.from("planos_viagem").insert(data);if(error){msg(error.message);return}clearPlanner();await load();page("planner");msg("Plano de viagem guardado.")};
document.addEventListener("click",async e=>{const b=e.target.closest("[data-plan-edit],[data-plan-delete]");if(!b)return;const id=b.dataset.planEdit||b.dataset.planDelete,p=plans.find(x=>x.id===id);if(!p)return;if(b.dataset.planDelete){if(!confirm("Eliminar este plano?"))return;const {error}=await db.from("planos_viagem").delete().eq("id",id);if(error)msg(error.message);else{await load();msg("Plano eliminado.")}}else{clearPlanner();editPlan=p.id;for(const [k,v]of Object.entries(p)){const el=plannerForm.elements.namedItem(k);if(el)el.value=v??""}plannerStops=Array.isArray(p.paragens)?p.paragens.map(s=>({...s})):[];page("planner");renderPlanner();$("plannerStatus").textContent="Plano carregado. Podes alterar e guardar."}});

/* Estatísticas calculadas apenas a partir dos registos privados carregados. */
const statsFilters=["statsFrom","statsTo","statsVehicle","statsState"];
function statKm(v){const start=v.km_inicial==null?null:Number(v.km_inicial),end=v.km_final==null?null:Number(v.km_final);if(start!=null&&end!=null&&Number.isFinite(start)&&Number.isFinite(end)&&end>=start)return end-start;const n=Number(v.km_percorridos);return v.km_percorridos!=null&&Number.isFinite(n)&&n>=0?n:null}
function statsData(){const from=$("statsFrom").value,to=$("statsTo").value,plate=$("statsVehicle").value,state=$("statsState").value;return trips.filter(v=>{const d=v.data_viagem||"";return (!from||d>=from)&&(!to||d<=to)&&(!plate||String(v.matricula||"").trim()===plate)&&(state==="all"||v.estado===state)})}
function statsBars(target,entries,formatter){const root=$(target);if(!entries.length){root.innerHTML='<p class="stat-empty">Sem dados para os filtros selecionados.</p>';return}const max=Math.max(1,...entries.map(x=>x[1]));root.innerHTML=entries.map(([name,n])=>'<div class="stat-bar"><span title="'+esc(name)+'">'+esc(name)+'</span><div class="stat-track"><div class="stat-fill" style="width:'+Math.max(0,Math.min(100,n/max*100))+'%"></div></div><span class="stat-value">'+esc(formatter(n))+'</span></div>').join("")}
function renderAnalytics(){if(!$("statsKpis"))return;const plate=$("statsVehicle"),selected=plate.value;const plates=[...new Set(trips.map(v=>String(v.matricula||"").trim()).filter(Boolean))].sort((a,b)=>a.localeCompare(b,"pt"));plate.innerHTML='<option value="">Todas as matrículas</option>'+plates.map(v=>'<option value="'+esc(v)+'">'+esc(v)+'</option>').join("");if(plates.includes(selected))plate.value=selected;const rows=statsData(),complete=rows.filter(v=>v.estado!=="rascunho"),valid=complete.map(v=>({...v,_km:statKm(v)})).filter(v=>v._km!=null),km=valid.reduce((a,v)=>a+v._km,0);const days=new Set(complete.map(v=>v.data_viagem).filter(Boolean)).size;const guides=new Set(complete.map(v=>String(v.numero_guia||"").trim()).filter(Boolean)).size;const metrics=[["Viagens concluídas",complete.length],["Km registados",fmt(km)],["Dias com serviços",days],["Guias distintas",guides],["Média km / viagem com km",valid.length?fmt(km/valid.length):"—"],["Viagens sem km",complete.length-valid.length]];$("statsKpis").innerHTML=metrics.map(([name,n])=>'<div class="card"><div class="muted">'+esc(name)+'</div><div class="num">'+esc(n)+'</div></div>').join("");const monthly=new Map();for(const v of valid){const key=String(v.data_viagem||"").slice(0,7);if(/^\d{4}-\d{2}$/.test(key))monthly.set(key,(monthly.get(key)||0)+v._km)}statsBars("statsMonthly",[...monthly].sort((a,b)=>a[0].localeCompare(b[0])).slice(-18),n=>fmt(n)+" km");const companiesCount=new Map();for(const v of complete)for(const name of [v.empresa_carga,v.empresa_descarga]){const label=String(name||"").trim();if(label){const key=label.toLocaleLowerCase("pt-PT");const entry=companiesCount.get(key)||{name:label,count:0};entry.count++;companiesCount.set(key,entry)}}statsBars("statsCompanies",[...companiesCount.values()].sort((a,b)=>b.count-a.count||a.name.localeCompare(b.name,"pt")).slice(0,10).map(x=>[x.name,x.count]),n=>n+" operações");const vehicles=new Map();for(const v of complete){const key=String(v.matricula||"Sem matrícula").trim();vehicles.set(key,(vehicles.get(key)||0)+1)}statsBars("statsVehicles",[...vehicles].sort((a,b)=>b[1]-a[1]).slice(0,10),n=>n+" viagens");$("statsSummary").textContent=rows.length+" registos no filtro · "+complete.length+" concluídos · "+(rows.length-complete.length)+" rascunhos · "+valid.length+" viagens com quilómetros válidos. A contagem de operações por empresa soma cargas e descargas, podendo contar a mesma empresa duas vezes numa viagem."}
for(const id of statsFilters)$(id).addEventListener("change",renderAnalytics);
function statsRange(from,to){$("statsFrom").value=from;$("statsTo").value=to;renderAnalytics()}
$("statsThisMonth").onclick=()=>{const d=new Date(),year=d.getFullYear(),month=String(d.getMonth()+1).padStart(2,"0");statsRange(year+"-"+month+"-01",year+"-"+month+"-"+String(new Date(year,d.getMonth()+1,0).getDate()).padStart(2,"0"))};
$("statsThisYear").onclick=()=>{const year=new Date().getFullYear();statsRange(year+"-01-01",year+"-12-31")};
$("statsAllTime").onclick=()=>statsRange("","");
$("statsExport").onclick=()=>{const rows=statsData();if(!rows.length){msg("Não existem viagens para exportar.");return}const columns=[["data_viagem","Data"],["numero_guia","Guia"],["estado","Estado"],["matricula","Matrícula"],["empresa_carga","Empresa carga"],["local_carga","Local carga"],["empresa_descarga","Empresa descarga"],["local_descarga","Local descarga"],["km_inicial","Km inicial"],["km_final","Km final"],["km","Km percorridos"]];const safe=v=>{let s=String(v??"");if(/^[\s]*[=+@-]/.test(s))s="'"+s;return '"'+s.replace(/"/g,'""')+'"'};const lines=[columns.map(c=>safe(c[1])).join(";"),...rows.map(v=>columns.map(([k])=>safe(k==="km"?(statKm(v)??""):v[k])).join(";"))];const blob=new Blob(["\ufeff"+lines.join("\r\n")],{type:"text/csv;charset=utf-8"});const url=URL.createObjectURL(blob),a=document.createElement("a");a.href=url;a.download="diario-de-bordo-estatisticas-"+new Date().toISOString().slice(0,10)+".csv";a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)};

function renderSiteCompanies(){const select=$("siteCompany"),current=select.value;select.innerHTML='<option value="">Selecionar empresa…</option>'+companies.map(c=>'<option value="'+esc(c.id)+'">'+esc(c.nome)+'</option>').join("");if(companies.some(c=>c.id===current))select.value=current;renderSites()}
function renderSites(){const id=$("siteCompany").value,rows=sites.filter(s=>s.empresa_id===id);$("siteList").innerHTML=rows.map(s=>'<div class="item"><div><b>'+esc(s.nome)+'</b><div class="muted">'+esc(s.morada)+' · '+esc(s.localidade||"")+'</div><div class="muted">'+esc(s.tipo.replace("_"," / "))+' · '+esc(s.notas||"")+'</div></div><div><button type="button" data-site-edit="'+s.id+'">Editar</button> <button type="button" data-site-delete="'+s.id+'">Eliminar</button></div></div>').join("")||'<p class="muted">Sem instalações registadas para esta empresa.</p>'}
function resetSite(){$("siteForm").reset();editSite=null}
$("siteCompany").onchange=()=>{resetSite();renderSites()};
$("siteCancel").onclick=resetSite;
$("siteForm").onsubmit=async e=>{e.preventDefault();const companyId=$("siteCompany").value;if(!companyId){msg("Seleciona primeiro a empresa.");return}const data={user_id:user.id,empresa_id:companyId};for(const[k,v]of new FormData(e.target))data[k]=String(v).trim()||null;for(const k of ["latitude","longitude"])data[k]=data[k]==null?null:Number(data[k]);if((data.latitude==null)!==(data.longitude==null)){msg("Preenche ambas as coordenadas ou nenhuma.");return}const result=editSite?await db.from("empresa_instalacoes").update(data).eq("id",editSite):await db.from("empresa_instalacoes").insert(data);if(result.error){msg(result.error.message);return}resetSite();await load();$("siteCompany").value=companyId;renderSites();page("companies");msg("Instalação guardada.")};
document.addEventListener("click",async e=>{const button=e.target.closest("[data-site-edit],[data-site-delete]");if(!button)return;const id=button.dataset.siteEdit||button.dataset.siteDelete,site=sites.find(s=>s.id===id);if(!site)return;if(button.dataset.siteEdit){$("siteCompany").value=site.empresa_id;editSite=id;for(const[k,v]of Object.entries(site)){const field=$("siteForm").elements.namedItem(k);if(field)field.value=v??""}renderSites();$("siteForm").scrollIntoView({behavior:"smooth"})}else{if(!confirm("Eliminar esta instalação?"))return;const r=await db.from("empresa_instalacoes").delete().eq("id",id);if(r.error)msg(r.error.message);else{await load();msg("Instalação eliminada.")}}});
